int a = 10;
int b = 25;
int sum_i = a + b;           // Standard integer addition (35)

double x = 4.5;
double y = 1.2;
double sum_d = x + y;        // Floating point addition (5.7)

// Promotion example (short promoted to int)
short s = 3;
int result_p = s + a;        // result_p is 38 (int)

// Pointer Arithmetic
char data[] = "ABCDE";
char* ptr = data;

// Advance pointer 3 bytes (sizeof(char) * 3)
char third_char = *(ptr + 3);  // 'D'

// Array indexing shorthand
char fourth_char = *(data + 4); // 'E'
